<template>
  <div ref="scrollEl" class="flex-1 min-h-0 overflow-y-auto px-1 pb-2">
    <ChatCornerElement ref="topEl" @vue:mounted="onTopElMount" @vue:unmounted="onTopElUnmount" />
    <ChatsListItem v-for="value in chats.items" ref="chatEls" :key="value.id!" :chat="value" class="my-1" />
    <ChatCornerElement ref="bottomEl" @vue:mounted="onBottomElMount" @vue:unmounted="onBottomElUnmount" />
  </div>
</template>

<script setup lang="ts">
import { useGetChatCursorList, type ChatsData, type ChatItem } from '~/composables/supabase/useChatList';

interface Props {
  chats: ChatsData;
  params: {
    limit: number;
    archived: boolean;
  };
}

const props = defineProps<Props>();

const scrollEl = useTemplateRef('scrollEl');
const topEl = useTemplateRef('topEl');
const bottomEl = useTemplateRef('bottomEl');
const chatEls = useTemplateRef('chatEls');

const cache = useQueryCache();

function isNearBottom(el: HTMLElement | undefined, px = 40) {
  if (!el) return false;
  return el.scrollHeight - (el.scrollTop + el.clientHeight) <= px;
}

function captureAnchor() {
  const el = scrollEl.value;
  if (!el) return null;

  return {
    scrollTop: el.scrollTop,
    scrollHeight: el.scrollHeight,
    nearBottom: isNearBottom(el),
  };
}

function restoreAnchor(before: ReturnType<typeof captureAnchor>, type: 'new' | 'old') {
  const el = scrollEl.value;
  if (!el || !before) return;

  const delta = el.scrollHeight - before.scrollHeight;

  if (type === 'old') el.scrollTop = before.scrollTop;
  if (type === 'new') el.scrollTop = before.scrollTop + delta;
}

function patchTimeline(updater: (prev: ChatsData) => ChatsData) {
  cache.setQueryData(['chats', ...Object.values(props.params)], (prev?: ChatsData) => {
    const base: ChatsData = prev ?? {
      items: [],
      error: null,
      newestId: null,
      oldestId: null,
      hasOlder: true,
      hasNewer: true,
    };
    return updater(base);
  });
}

async function loadDataBatch(type: 'new' | 'old') {
  if (type === 'old' && !props.chats?.hasOlder) return;
  if (type === 'new' && !props.chats?.hasNewer) return;
  if ((props.chats.items?.length ?? 0) < props.params.limit) return;

  const before = captureAnchor();

  const res = await useGetChatCursorList({
    archived: props.params.archived,
    before_cursor: type === 'old' ? props.chats.oldestId : null,
    after_cursor: type === 'new' ? props.chats.newestId : null,
    chat_limit: props.params.limit,
  });

  if (res?.error) {
    captureExceptionToSentry(new Error('Failed to get chat list batch: ' + res.error.message));
  }

  const batch = dedupeDescByCursor<ChatItem>(res.data ?? []);

  if (!batch.length) {
    patchTimeline((prev) => ({
      ...prev,
      error: null,
      hasOlder: type === 'old' ? false : prev.hasOlder,
      hasNewer: type === 'new' ? false : prev.hasNewer,
    }));
    return;
  }

  patchTimeline((prev) => {
    const list = type === 'new' ? [...batch, ...(prev.items ?? [])] : [...(prev.items ?? []), ...batch];

    const listDeduped = dedupeDescByCursor<ChatItem>(list);

    return {
      items: listDeduped,
      error: res.error,
      newestId: listDeduped[0]?.cursor ?? null,
      oldestId: listDeduped.at(-1)?.cursor ?? null,
      hasOlder: type === 'old' ? res.data?.length === props.params.limit : prev.hasOlder,
      hasNewer: type === 'new' ? res.data?.length === props.params.limit : prev.hasNewer,
    };
  });

  await nextTick();
  restoreAnchor(before, type);
}

const route = useRoute();

onMounted(async () => {
  if (route.name === 'chats-id') {
    await nextTick();
    const component = chatEls.value?.find((el) => el?.$props.chat.id === route.params.id);
    if (component) component.$el.scrollIntoView({ block: 'nearest', behavior: 'auto', container: 'nearest' });
  }
});

const bottomElObserver = ref<IntersectionObserver | null>(null);

function onBottomElMount() {
  const root = scrollEl.value;
  if (!root) return;

  bottomElObserver.value = new IntersectionObserver(
    (entries) => {
      if (entries[0]?.isIntersecting) loadDataBatch('old');
    },
    { rootMargin: '100px', root }
  );
  bottomElObserver.value.observe(bottomEl.value!.$el);
}

function onBottomElUnmount() {
  bottomElObserver.value?.disconnect();
  bottomElObserver.value = null;
}

const topElObserver = ref<IntersectionObserver | null>(null);

function onTopElMount() {
  const root = scrollEl.value;
  if (!root) return;

  topElObserver.value = new IntersectionObserver(
    (entries) => {
      if (entries[0]?.isIntersecting) loadDataBatch('new');
    },
    { rootMargin: '100px', root: scrollEl.value }
  );
  topElObserver.value.observe(topEl.value!.$el);
}

function onTopElUnmount() {
  topElObserver.value?.disconnect();
  topElObserver.value = null;
}
</script>
