<template>
  <Card class="p-0 rounded-none sm:rounded-md h-full">
    <CardContent class="w-full h-full flex !p-0">
      <ChatsSidebar
        :chat-info-data="chatInfoData"
        :loading="isChatInfoLoading || isLoadingChats"
        :chats="chatsData"
        :params="params"
        :error="chatsError?.message || null"
        :class="
          cn('w-full sm:max-w-[220px] lg:max-w-[320px] flex flex-col gap-2', {
            'hidden sm:flex': !isInitPage,
          })
        "
      />
      <Separator orientation="vertical" :class="cn('hidden sm:block')" />
      <div :class="cn('w-full h-full flex flex-col flex-1 min-h-0 min-w-0', { 'hidden sm:block': isInitPage })">
        <NuxtPage :chat-info-data="chatInfoData" :is-chat-info-loading="isChatInfoLoading" />
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { cn } from '@/lib/utils';
import { useGetChatInfo } from '~/composables/supabase/useChatInfo';
import {
  useGetChatCursorList,
  useGetChatListCursorAt,
  type ChatsData,
  type ChatItem,
} from '~/composables/supabase/useChatList';
import { isEqual } from 'lodash';
import type { PostgrestSingleResponse } from '@supabase/supabase-js';
import type { GetChatInfoResponse } from '~/composables/supabase/useChatInfo';

const route = useRoute();
const isInitPage = computed(() => route.name === 'chats');

const chatId = computed(() => (route.name === 'chats-id' ? route.params.id : null));

const { userId } = useUserRole();

const { data: chatInfoData, isLoading: isChatInfoLoading } = useQuery({
  key: () => ['chatInfo.id', chatId.value],
  query: async () => {
    const data = await useGetChatInfo({ chat_id: chatId.value });
    if (data.error) {
      captureExceptionToSentry(new Error('Failed to get chat by id: ' + data.error.message));
      showToastError('Failed to get chat info');
      navigateTo({ name: 'chats' }, { replace: true });
    }
    return data;
  },
  enabled: () => !!chatId.value,
});

const params = computed(() => {
  const limit = Number(route.query.chatLimit) || 18;
  const result = {
    limit: limit,
    archived: Boolean(route.query.archived),
  };
  return result;
});

const prevParams = ref<{ archived: boolean; limit: number } | null>(null);

const {
  data: chatsData,
  isLoading: isLoadingChats,
  error: chatsError,
} = useQuery({
  key: () => ['chats', ...Object.values(params.value)],
  query: async (): Promise<ChatsData | undefined> => {
    if (isEqual(params.value, prevParams.value)) {
      const queryCache = useQueryCache();
      return queryCache.getQueryData(['chats', ...Object.values(params.value)]);
    }
    prevParams.value = params.value;
    const chatsCursor = route.name === 'chats-id' ? (chatInfoData.value?.data?.cursor ?? null) : null;
    let res = undefined;
    if (chatsCursor)
      res = await useGetChatListCursorAt({
        archived: params.value.archived,
        at_cursor: chatsCursor,
        chat_limit: params.value.limit,
      });
    else
      res = await useGetChatCursorList({
        archived: params.value.archived,
        before_cursor: null,
        after_cursor: null,
        chat_limit: params.value.limit,
      });

    if (res.error) {
      console.log(res.error);
      captureExceptionToSentry(new Error('Failed to get chat list: ' + res.error.message));
      throw new Error('Failed to get chat list');
    }
    return {
      items: res.data ?? [],
      error: res.error,
      newestId: res.data?.[0]?.cursor ?? null,
      oldestId: res.data?.at(-1)?.cursor ?? null,
      hasOlder: (res.data?.length ?? 0) === params.value.limit,
      hasNewer: (res.data?.length ?? 0) === params.value.limit,
    };
  },
  enabled: () => Boolean(route.name === 'chats-id' ? !!chatInfoData.value?.data : true),
  staleTime: 0,
});

//TODO move and refactor processing messages from realtime
const queryCache = useQueryCache();

function increaseUnreadChatsCounter() {
  updateChatCounter(1);
}

function decreaseUnreadChatsCounter() {
  updateChatCounter(-1);
}

function updateChatCounter(number: number) {
  queryCache.setQueryData<PostgrestSingleResponse<number> | undefined>(['unreadChatCount'], (prevData) => {
    if (!prevData) return prevData;

    if (prevData.data === undefined || prevData.data === null) return prevData;

    return {
      ...prevData,
      data: prevData.data + number,
    };
  });
}

function onNewMessageInChatList(newItem: ChatItem) {
  queryCache.setQueryData<ChatsData | undefined>(['chats', ...Object.values(params.value)], (prevParams) => {
    if (!prevParams) return prevParams;

    if (!prevParams.items.find((chat) => chat.id === newItem.id)) {
      if (
        !newItem.muted_until &&
        !newItem.archived_at &&
        newItem.last_read_message_id &&
        newItem.last_message_id &&
        newItem.last_message_id - newItem.last_read_message_id === 1
      )
        increaseUnreadChatsCounter();

      if (chatsData.value?.hasNewer) return prevParams;

      if (params.value.archived !== Boolean(newItem.archived_at)) return prevParams;

      return {
        ...prevParams,
        items: [newItem, ...prevParams.items],
      };
    } else {
      const processedItems = dedupeDescByCursor<ChatItem>(
        prevParams.items.map((item) => {
          if (item.id === newItem.id) {
            if (
              item.last_read_message_id &&
              item.last_read_message_id === (item.last_message_id || 0) &&
              !item.muted_until &&
              !item.archived_at
            ) {
              increaseUnreadChatsCounter();
            }
            return newItem;
          }
          return item;
        })
      );
      return {
        ...prevParams,
        items: processedItems,
      };
    }
  });
}

function onNewChatItem(newItem: ChatItem) {
  if (Boolean(newItem.archived_at) === params.value.archived)
    queryCache.setQueryData<ChatsData | undefined>(['chats', ...Object.values(params.value)], (prevParams) => {
      if (!prevParams) return prevParams;

      if (chatsData.value?.hasNewer) return prevParams;

      return {
        ...prevParams,
        items: [newItem, ...prevParams.items],
      };
    });

  const isNewItemArchived = newItem.archived_at;
  const isNewItemMuted = newItem.muted_until;
  if (!isNewItemArchived && !isNewItemMuted) increaseUnreadChatsCounter();
}

function onDeleteChatItem(newItem: ChatItem) {
  if (Boolean(newItem.archived_at) === params.value.archived)
    queryCache.setQueryData<ChatsData | undefined>(['chats', ...Object.values(params.value)], (prevParams) => {
      if (!prevParams) return prevParams;

      return {
        ...prevParams,
        items: prevParams.items.filter((item) => item.id !== newItem.id),
      };
    });

  const isNewItemMuted = newItem.muted_until;
  const isNewItemArchived = newItem.archived_at;
  if (
    (!newItem.last_read_message_id || newItem.last_read_message_id < (newItem.last_message_id || 0)) &&
    !isNewItemMuted &&
    !isNewItemArchived
  )
    decreaseUnreadChatsCounter();
}

function onArchiveChatItem(newItem: ChatItem) {
  const isNewItemArchived = newItem.archived_at;
  const isNewItemMuted = newItem.muted_until;
  queryCache.setQueryData<ChatsData | undefined>(['chats', ...Object.values(params.value)], (prevParams) => {
    if (!prevParams) return prevParams;
    let items;
    if (isNewItemArchived) {
      if (params.value.archived) {
        items = dedupeDescByCursor<ChatItem>([newItem, ...prevParams.items]);
      } else {
        items = prevParams.items.filter((item) => item.id !== newItem.id);
      }
    } else {
      if (params.value.archived) {
        items = prevParams.items.filter((item) => item.id !== newItem.id);
      } else {
        items = dedupeDescByCursor<ChatItem>([newItem, ...prevParams.items]);
      }
    }
    return {
      ...prevParams,
      items: items,
    };
  });

  if (
    (!newItem.last_read_message_id || newItem.last_read_message_id < (newItem.last_message_id || 0)) &&
    !isNewItemMuted
  ) {
    if (isNewItemArchived) {
      decreaseUnreadChatsCounter();
    } else {
      increaseUnreadChatsCounter();
    }
  }
}

function onUpdateChatItem(newItem: ChatItem) {
  queryCache.setQueryData<ChatsData | undefined>(['chats', ...Object.values(params.value)], (prevParams) => {
    if (!prevParams) return prevParams;

    const processedItems = dedupeDescByCursor<ChatItem>(
      prevParams.items.map((item) => {
        if (item.id === newItem.id) return newItem;
        return item;
      })
    );
    return {
      ...prevParams,
      items: processedItems,
    };
  });
}

function onReadMessageChatItem(newItem: ChatItem) {
  queryCache.setQueryData<ChatsData | undefined>(['chats', ...Object.values(params.value)], (prevParams) => {
    if (!prevParams) return prevParams;

    const processedItems = prevParams.items.map((item) => {
      if (item.id === newItem.id) return newItem;
      return item;
    });
    return {
      ...prevParams,
      items: processedItems,
    };
  });

  const isNewItemMuted = newItem.muted_until;
  const isNewItemArchived = newItem.archived_at;
  if (
    newItem.last_read_message_id &&
    newItem.last_read_message_id === (newItem.last_message_id || 0) &&
    !isNewItemMuted &&
    !isNewItemArchived
  )
    decreaseUnreadChatsCounter();

  if (newItem.id === chatId.value) {
    queryCache.setQueryData<GetChatInfoResponse | undefined>(['chatInfo.id', chatId.value], (prevParams) => {
      if (!prevParams?.data) return prevParams;

      prevParams.data.last_read_message_id = newItem.last_read_message_id;
      return prevParams;
    });
  }
}

function onEditMessageChatItem(newItem: ChatItem) {
  queryCache.setQueryData<ChatsData | undefined>(['chats', ...Object.values(params.value)], (prevParams) => {
    if (!prevParams) return prevParams;

    const processedItems = prevParams.items.map((item) => {
      if (item.id === newItem.id) return newItem;
      return item;
    });
    return {
      ...prevParams,
      items: processedItems,
    };
  });
}

function onDeleteMessageChatItem(newItem: ChatItem) {
  queryCache.setQueryData<ChatsData | undefined>(['chats', ...Object.values(params.value)], (prevParams) => {
    if (!prevParams) return prevParams;

    const processedItems = prevParams.items.map((item) => {
      if (item.id === newItem.id) return newItem;
      return item;
    });
    return {
      ...prevParams,
      items: processedItems,
    };
  });
  const isNewItemMuted = newItem.muted_until;
  const isNewItemArchived = newItem.archived_at;
  if (
    newItem.last_read_message_id &&
    newItem.last_read_message_id === (newItem.last_message_id || 0) &&
    !isNewItemMuted &&
    !isNewItemArchived
  )
    decreaseUnreadChatsCounter();
}

function onMuteChatItemChange(newItem: ChatItem) {
  queryCache.setQueryData<ChatsData | undefined>(['chats', ...Object.values(params.value)], (prevParams) => {
    if (!prevParams) return prevParams;

    const processedItems = prevParams.items.map((item) => {
      if (item.id === newItem.id) return newItem;
      return item;
    });
    return {
      ...prevParams,
      items: processedItems,
    };
  });
}

const unsub = ref<any>(null);

onMounted(async () => {
  const { $realtimeManager } = useNuxtApp();
  unsub.value = $realtimeManager.register((supabase) => {
    return supabase
      .channel(`chat-list:${userId.value}`, {
        config: { private: true, broadcast: { ack: true } },
      })
      .on('broadcast', { event: 'chat_list_new_message' }, async (event: { payload: { record: ChatItem } }) => {
        onNewMessageInChatList(event.payload.record);
      })
      .on('broadcast', { event: 'chat_list_new_chat' }, async (event: { payload: { record: ChatItem } }) => {
        onNewChatItem(event.payload.record);
      })
      .on('broadcast', { event: 'chat_list_delete_chat' }, async (event: { payload: { record: ChatItem } }) => {
        onDeleteChatItem(event.payload.record);
        if (route.name === 'chats-id' && String(route.params.id) === String(event.payload.record.id)) {
          navigateTo({ name: 'chats', query: route.query }, { replace: true });
        }
      })
      .on('broadcast', { event: 'chat_list_update_chat' }, async (event: { payload: { record: ChatItem } }) => {
        onUpdateChatItem(event.payload.record);
      })
      .on('broadcast', { event: 'chat_list_archive_chat' }, async (event: { payload: { record: ChatItem } }) => {
        onArchiveChatItem(event.payload.record);
      })
      .on('broadcast', { event: 'chat_list_read_message' }, async (event: { payload: { record: ChatItem } }) => {
        onReadMessageChatItem(event.payload.record);
      })
      .on('broadcast', { event: 'chat_list_edit_message' }, async (event: { payload: { record: ChatItem } }) => {
        onEditMessageChatItem(event.payload.record);
      })
      .on('broadcast', { event: 'chat_list_delete_message' }, async (event: { payload: { record: ChatItem } }) => {
        onDeleteMessageChatItem(event.payload.record);
      })
      .on('broadcast', { event: 'chat_list_mute_chat' }, async (event: { payload: { record: ChatItem } }) => {
        onMuteChatItemChange(event.payload.record);
      })
      .on('broadcast', { event: 'chat_list_unmute_chat' }, async (event: { payload: { record: ChatItem } }) => {
        onMuteChatItemChange(event.payload.record);
      })
      .on('system', { event: '*' }, async (event) => {
        if (event?.message?.includes('Token has expired')) {
          console.warn('Token has expired, refreshing...');
          await $realtimeManager.refresh();
        }
      })
      .subscribe();
  });
});

onUnmounted(() => {
  if (unsub.value) unsub.value();
  const { $realtimeManager } = useNuxtApp();
  $realtimeManager.closeSocketConnection();
});

const pageTitle = computed(() =>
  chatInfoData?.value?.data?.title ? `${chatInfoData.value.data.title} Chat` : 'Chats'
);

useHead({
  title: pageTitle,
});
</script>
