<template>
  <div>
    <ChatsNewChatDialog v-if="isAdminOrManager" />
    <FilterTabsNav :items="tabs" class="min-h-fit" stretched />
    <AppLoader
      v-if="loading && (!chats || chats?.items.length === 0)"
      subject="chats"
      variant="table"
      class="h-full w-full"
    />
    <AppError
      v-else-if="error"
      :message="error"
      variant="table"
      class="h-full w-full"
      action-text=""
      title="Failed to load data"
    />
    <AppEmpty v-else-if="!chats?.items.length" variant="table" subject="chats" class="h-full w-full" />
    <ChatsList v-else-if="chats" :chats="chats" :params="params" />
  </div>
</template>

<script setup lang="ts">
import { type ChatsData } from '~/composables/supabase/useChatList';
import { ArchiveIcon, MessageCircleIcon } from 'lucide-vue-next';
import type { FunctionalComponent } from 'vue';

interface Props {
  loading: boolean;
  error: string | null;
  chats: ChatsData | undefined;
  params: {
    limit: number;
    archived: boolean;
  };
}

const props = defineProps<Props>();

const { isAdminOrManager } = useUserRole();

const route = useRoute();

const tabs = computed(() => {
  const icon = (icon: FunctionalComponent) => ({ icon: icon, class: 'size-5 mr-1' });
  return [
    {
      label: 'Active',
      to: { ...route, query: { ...route.query, archived: undefined } },
      selected: !props.params.archived,
      icon: icon(MessageCircleIcon),
    },
    {
      label: 'Archived',
      to: { ...route, query: { ...route.query, archived: true } },
      selected: props.params.archived,
      icon: icon(ArchiveIcon),
    },
  ];
});
</script>
