<template>
  <Dialog
    v-model:open="model"
    @update:open="
      (value) => {
        if (value) selectedUsers = [];
      }
    "
  >
    <DialogTrigger as-child>
      <div class="px-2 pt-2">
        <Button :prepend-icon="PlusIcon" variant="outline" class="w-full">Start new chat</Button>
      </div>
    </DialogTrigger>
    <DialogContent class="rounded-lg max-w-xs sm:max-w-sm gap-6" @vue:unmounted="selectedUsers = []">
      <DialogHeader class="gap-y-2 text-left">
        <DialogTitle class="text-xl">Select user to start chat with</DialogTitle>
      </DialogHeader>
      <div>
        <LabeledMultiCombobox
          v-model="selectedUsers"
          :items="processedUsers"
          placeholder="Select users"
          empty-text="No users found."
          items-plural-name="users"
          :icon="UserIcon"
          :loading="isLoading"
          :error="data?.error?.message || error"
          :max-selected-items="1"
        >
          <template #item-prefix="{ item }">
            <ChatsUserAvatar :avatar-url="item.avatarUrl" :name="item.displayName" size="xs" class="mr-2 shrink-0" />
          </template>
          <template #selected-prefix="{ item }">
            <ChatsUserAvatar :avatar-url="item.avatarUrl" :name="item.displayName" size="xs" class="shrink-0" />
          </template>
        </LabeledMultiCombobox>
      </div>
      <DialogFooter>
        <div class="flex flex-wrap justify-end gap-2">
          <DialogClose as-child>
            <Button variant="outline" class="h-10 px-4">Cancel</Button>
          </DialogClose>
          <NuxtLink
            v-if="selectedUsers.length"
            :to="{
              name: 'chats-send',
              query: { users: selectedUsers.length ? selectedUsers.map((user) => user.value) : undefined },
            }"
          >
            <Button class="h-10 px-4" :disabled="selectedUsers.length === 0" @click="model = false">
              Start Chat
            </Button>
          </NuxtLink>
          <Button v-else class="h-10 px-4" disabled> Start Chat </Button>
        </div>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { useUsers } from '~/composables/supabase/useUsers';
import { UserIcon, PlusIcon } from 'lucide-vue-next';

const model = defineModel<boolean>('open', { default: false });
const selectedUsers = ref<SelectItem<string>[]>([]);

const { data, isLoading, error } = useQuery({
  key: () => ['chat.users', model.value],
  query: () => useUsers(),
  enabled: () => !!model.value,
});

const processedUsers = computed(() => {
  if (!data.value?.data?.length) return [];
  return data.value.data.map((user) => ({
    name: `${user.display_name} (${user.role?.replaceAll('_', ' ').toLowerCase() || ''})`,
    value: user.id,
    avatarUrl: user.avatar_url,
    displayName: user.display_name,
  }));
});
</script>
