import type { QueryData, PostgrestSingleResponse, PostgrestError } from '@supabase/supabase-js';
import { withSupabase } from './useCheckSupabaseClient';
import type { Database } from '~/types/schema';

type GetChatInfoArgs = Database['private']['CompositeTypes']['get_chat_details_input'];

export const useGetChatInfo = async (data: GetChatInfoArgs) => {
  return withSupabase((supabase) => supabase.rpc('get_chat_details', { input: data }));
};

export type ChatInfo = Database['private']['Functions']['get_chat_details']['Returns'];
export type ChatType = Database['private']['Tables']['chats']['Row']['type'];
export type GetChatInfoResponse = PostgrestSingleResponse<QueryData<ReturnType<typeof useGetChatInfo>>>;
