import type { QueryData } from '@supabase/supabase-js';
import { withSupabase } from './useCheckSupabaseClient';

export const useUsers = async () => {
  const { userId } = useUserRole();
  return withSupabase((supabase) =>
    supabase
      .from('profiles')
      .select()
      .neq('id', userId.value || '')
      .eq('is_deactivated', false)
  );
};

export type GetUsersResponse = QueryData<ReturnType<typeof useUsers>>;
