<template>
  <NuxtLink
    :to="{ name: 'chats-id', params: { id: chat.id! }, query: { ...route.query } }"
    :class="
      cn('flex items-center gap-2 w-full pl-1 pr-2 py-2 hover:bg-accent-blind cursor-pointer rounded-lg duration-300', {
        '!bg-accent': isActive,
      })
    "
  >
    <ChatsUserAvatar :avatar-url="chat.avatar_url" :name="chat.title" size="sm" />
    <div class="flex flex-col gap-1 min-w-0 flex-1 min-h-full self-stretch justify-center">
      <div class="text-sm flex gap-1 items-center min-w-0 justify-between">
        <div class="flex gap-1 items-center min-w-0 flex-1">
          <component
            :is="projectType"
            v-if="projectType"
            :class="cn('w-5 h-5 shrink-0', { 'text-yellow-500 animate-pulse': isGraceChat })"
          />
          <p class="truncate font-medium min-w-0 flex-1">
            {{ chat.title }}
          </p>
        </div>
        <VolumeOffIcon v-if="chat.muted_until" class="w-4 h-4 shrink-0 text-muted-foreground" />
        <span v-if="messageTime" class="text-muted-foreground shrink-0 text-xs">
          {{ messageTime }}
        </span>
      </div>
      <div class="text-sm text-accent-foreground flex gap-1 items-center min-w-0">
        <p v-if="chat.last_message_preview || chat.last_message_metadata" class="truncate w-full">
          <span v-if="chat.last_message_type === 'USER'">{{ userMessagePreview }}</span>
          <span
            v-else-if="chat.last_message_type === 'SYSTEM' && isSystemMessageMetadata(chat.last_message_metadata)"
            class="text-muted-foreground"
          >
            <span v-if="isChatParticipantSystemMessage(chat.last_message_metadata.event_body)">{{
              newParticipantmessageProcess(chat.last_message_metadata.event_body)
            }}</span>
          </span>
        </p>
        <Badge
          v-if="isChatUnread"
          :variant="chat.archived_at || chat.muted_until ? 'default' : 'info'"
          class="size-3 shrink-0 rounded-full px-1"
        />
      </div>
    </div>
  </NuxtLink>
</template>

<script setup lang="ts">
import { cn } from '@/lib/utils';
import type { ChatItem } from '~/composables/supabase/useChatList';
import { BriefcaseIcon, SparklesIcon, UserIcon, UserRoundIcon, VolumeOffIcon } from 'lucide-vue-next';
import type { SystemMessageMetadata, ChatParticypantMessageBody } from '@/composables/supabase/useChatMessages';
import type { UserMessageMetadata, UserMessageWithAttachments } from '~/composables/supabase/useChatMessages';
import { GRACE_ID } from '~/constants/chats/graceId';

interface Props {
  chat: ChatItem;
}

const props = defineProps<Props>();

const { timezone, userId } = useUserRole();

const route = useRoute();

const isActive = computed(() => route.name === 'chats-id' && route.params.id === props.chat.id);

const isGraceChat = computed(() => props.chat.dm_with_user_id === GRACE_ID && props.chat.type === 'DM');

const messageTime = computed(() => {
  if (!props.chat.last_message_at || !timezone.value) return null;
  const check = isSameZonedDayAsToday(props.chat.last_message_at, timezone.value);
  if (check) return formatDateTzToFormat(props.chat.last_message_at, 'hh:mm a', timezone.value)?.toLowerCase();
  else return formatDateTzToFormat(props.chat.last_message_at, 'MM/dd/yy', timezone.value);
});

const projectType = computed(() => {
  if (isGraceChat.value) return SparklesIcon;
  switch (props.chat.type) {
    case 'DM':
      return UserIcon;
    case 'CHANNEL':
      return BriefcaseIcon;
    case 'GROUP':
      return UserRoundIcon;
    default:
      return null;
  }
});

const isChatUnread = computed(() => {
  const chat = props.chat;
  const isLastMessageFromUser = chat.last_message_sender_id === userId.value; //TODO check what to do with last_message_sender_id in channels
  if (!chat.last_message_id) return false;
  return !isLastMessageFromUser && (!chat.last_read_message_id || chat.last_read_message_id < chat.last_message_id);
});

function isSystemMessageMetadata(metadata: unknown): metadata is SystemMessageMetadata {
  return props.chat.last_message_type === 'SYSTEM';
}

function isChatParticipantSystemMessage(eventBody: unknown): eventBody is ChatParticypantMessageBody {
  return (
    isSystemMessageMetadata(props.chat.last_message_metadata) &&
    props.chat.last_message_metadata.event_type === 'new_participant'
  );
}

function newParticipantmessageProcess(body: ChatParticypantMessageBody) {
  if (body.user_id === userId.value) return 'You were added to the chat';
  else return `User ${body.display_name} was added to the chat`;
}

const userMessagePreview = computed(() => {
  if (props.chat.last_message_preview) return props.chat.last_message_preview;
  else if (
    props.chat.last_message_metadata &&
    isUserMessageMetadata(props.chat.last_message_metadata) &&
    isUserMessageMetadataBodyWithAttachments(props.chat.last_message_metadata?.metadata_body)
  ) {
    if (props.chat.last_message_metadata.metadata_body.attachment_names)
      return props.chat.last_message_metadata.metadata_body.attachment_names.length > 1
        ? `${props.chat.last_message_metadata.metadata_body.attachment_names.length} files`
        : `File ${props.chat.last_message_metadata.metadata_body.attachment_names[0]}`;
    else return null;
  }
});

function isUserMessageMetadata(metadata: unknown): metadata is UserMessageMetadata {
  return props.chat.last_message_type === 'USER';
}

function isUserMessageMetadataBodyWithAttachments(body: unknown): body is UserMessageWithAttachments {
  return (
    !!body &&
    isUserMessageMetadata(body) &&
    'attachment_names' in body &&
    Array.isArray(body.attachment_names) &&
    body.attachment_names.length > 0
  );
}
</script>
