<template>
  <div :class="cn('flex flex-col gap-1.5 relative w-full')">
    <p v-if="label" class="text-sm">{{ label }}</p>
    <Popover v-model:open="open" class="relative">
      <PopoverAnchor as-child>
        <PopoverTrigger as-child>
          <Button
            variant="outline"
            role="combobox"
            :aria-expanded="open"
            :class="
              cn('w-full h-10 justify-between font-normal min-w-0', !modelValue.length && 'text-muted-foreground')
            "
          >
            <span class="flex items-center gap-2 flex-1 w-0 min-w-0">
              <component
                :is="icon"
                v-if="icon && !(modelValue.length === 1 && $slots['selected-prefix'])"
                class="h-4 w-4 shrink-0"
              />
              <slot v-if="modelValue.length === 1" name="selected-prefix" :item="modelValue[0]" />

              <span class="min-w-0 flex-1 truncate">
                <template v-if="modelValue.length === 0">
                  {{ placeholder }}
                </template>
                <template v-else-if="modelValue.length === 1">
                  {{ modelValue[0].name ?? modelValue[0].value }}
                </template>
                <template v-else>
                  {{ `${modelValue.length} ${itemsPluralName || 'items'}` }}
                </template>
              </span>
            </span>

            <component
              :is="loading ? Spinner : ChevronsUpDownIcon"
              class="ml-2 h-4 w-4 shrink-0"
              :class="!loading && modelValue?.length ? 'mr-6' : ''"
            />
          </Button>
        </PopoverTrigger>
        <XIcon
          v-if="!loading && modelValue.length"
          class="h-4 w-4 ml-2 shrink-0 absolute right-4 top-[0.75rem] cursor-pointer"
          @click.stop.prevent="modelValue = []"
        />
      </PopoverAnchor>
      <PopoverContent class="w-[var(--reka-popover-trigger-width)] p-0">
        <Command>
          <CommandInput v-if="items.length >= minItemsForSearch" :placeholder="inputPlaceholder" />
          <CommandList
            :class="
              cn(
                'relative z-0',
                items.length >= minItemsForSearch
                  ? 'max-h-[min(20rem,_calc(var(--reka-popover-content-available-height)-50px))]'
                  : 'max-h-[min(20rem,_calc(var(--reka-popover-content-available-height)-10px))]'
              )
            "
          >
            <div v-if="items.length === 0" class="py-6 text-center text-sm text-muted-foreground">
              {{ emptyText }}
            </div>
            <template v-else>
              <CommandEmpty>{{ emptyText }}</CommandEmpty>
              <CommandGroup>
                <CommandItem
                  v-for="item in items"
                  :key="item.name"
                  :value="item.value"
                  class="cursor-pointer"
                  @select="onChange(item)"
                >
                  <CheckIcon
                    :class="
                      cn(
                        'mr-2 h-4 w-4 shrink-0',
                        modelValue.find((elem) => elem.value === item.value) ? 'opacity-100' : 'opacity-0'
                      )
                    "
                  />
                  <slot name="item-prefix" :item="item" />
                  <span class="truncate">{{ item.name }}</span>
                </CommandItem>
              </CommandGroup>
            </template>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
    <p v-if="errorMessage && !isOffline" class="p-2 text-sm text-destructive select-none">{{ errorMessage }}</p>
  </div>
</template>

<script setup lang="ts" generic="T extends string">
import { CheckIcon, ChevronsUpDownIcon, XIcon } from 'lucide-vue-next';
import { cn } from '~/components/ui/utils';
import { FetchError } from 'ofetch';
import { Spinner } from '~/assets/icons';
import { PopoverAnchor } from 'reka-ui';

import { getErrorMessage } from '~/utils/getErrorMessage';

const { isOffline } = useNetworkStatus();

interface Props {
  label?: string;
  items: SelectItem<T>[];
  placeholder: string;
  inputPlaceholder?: string;
  emptyText: string;
  error?: FetchError | string | null;
  // nullIsAll: boolean; //Do we need it here?
  loading?: boolean;
  itemsPluralName: string;
  minItemsForSearch?: number;
  icon?: any;
  maxSelectedItems?: number;
}

const props = withDefaults(defineProps<Props>(), {
  placeholder: undefined,
  inputPlaceholder: undefined,
  emptyText: 'No items found.',
  error: undefined,
  label: undefined,
  loading: false,
  minItemsForSearch: 10,
  icon: undefined,
  maxSelectedItems: undefined,
});
const errorMessage = computed(() => getErrorMessage(props.error));

const open = defineModel<boolean>('open', { default: false });
const modelValue = defineModel<SelectItem<T>[]>({ default: [] });

function onChange(item: SelectItem<T>) {
  const isInValues = modelValue.value.find((elem) => elem.value === item.value);
  if (isInValues) modelValue.value = modelValue.value.filter((elem) => elem.value !== item.value);
  else if (props.maxSelectedItems === 1) {
    modelValue.value = [item];
    open.value = false;
  } else if ((props.maxSelectedItems && modelValue.value.length < props.maxSelectedItems) || !props.maxSelectedItems)
    modelValue.value.push(item);
}
</script>
